import React, { useState } from "react";

export default function RegistrationForm() {
  const [step, setStep] = useState(1);
  const [error, setError] = useState({});
  const [submitting, setSubmitting] = useState(false);

  const [form, setForm] = useState({
    // 🧍‍♂️ Basic Personal Information
    fullName: "",
    email: "",
    phone: "",
    dob: "",
    gender: "",
    location: "",

    // 🩺 Health & Lifestyle Information
    height: "",
    weight: "",
    fitnessLevel: "",
    medicalConditions: "",
    allergies: "",
    sleep: "",
    habits: "",

    // 🎯 Goals & Preferences
    goals: "",
    coachingStyle: "",
    workoutPreferences: "",
    dietaryPreferences: "",
    timeAvailability: "",
  });

  // ✅ Step-wise validation
  const Validate = () => {
    let e = {};

    if (step === 1) {
      if (!form.fullName.trim()) e.fullName = "Full Name is required";
      if (!form.email.trim()) e.email = "Email is required";
      if (!form.phone.trim()) e.phone = "Phone Number is required";
      if (!form.dob.trim()) e.dob = "Date of Birth is required";
      if (!form.gender.trim()) e.gender = "Gender is required";
      if (!form.location.trim()) e.location = "Location is required";
    }

    if (step === 2) {
      if (!form.height.trim()) e.height = "Height is required";
      if (!form.weight.trim()) e.weight = "Weight is required";
      if (!form.fitnessLevel.trim())
        e.fitnessLevel = "Current Fitness Level is required";
      if (!form.medicalConditions.trim())
        e.medicalConditions = "Medical Conditions are required";
      if (!form.sleep.trim()) e.sleep = "Sleep Patterns are required";
    }

    if (step === 3) {
      if (!form.goals.trim()) e.goals = "Health Goals are required";
      if (!form.coachingStyle.trim())
        e.coachingStyle = "Preferred Coaching Style is required";
      if (!form.timeAvailability.trim())
        e.timeAvailability = "Time Availability is required";
    }

    setError(e);
    return Object.keys(e).length === 0; // ✅ valid if no errors
  };

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // ✅ check validation before going next
  const nextStep = () => {
    if (Validate()) {
      setStep(step + 1);
    }
  };

  const prevStep = () => setStep(step - 1);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!Validate()) return; // stop if errors
    console.log("Form submitted:", form);
    alert("Registration successful!");
  };

  return (
    <div className="container mt-5" style={{ marginBottom: "100px" }}>
      <div
        className="card shadow-sm p-4"
        style={{ maxWidth: "600px", margin: "auto" }}
      >
        <h3 className="text-center mb-4">Health Coach Registration</h3>

        <form onSubmit={handleSubmit}>
          {/* Step 1: Basic Info */}
          {step === 1 && (
            <>
              <h5>🧍‍♂️ Basic Personal Information</h5>
              <div className="mb-3">
                <label className="form-label">Full Name</label>
                <input
                  type="text"
                  name="fullName"
                  value={form.fullName}
                  onChange={handleChange}
                  className={`form-control ${
                    error.fullName ? "is-invalid" : ""
                  }`}
                />
                {error.fullName && (
                  <div className="invalid-feedback">{error.fullName}</div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Email</label>
                <input
                  type="email"
                  name="email"
                  value={form.email}
                  onChange={handleChange}
                  className={`form-control ${error.email ? "is-invalid" : ""}`}
                />
                {error.email && (
                  <div className="invalid-feedback">{error.email}</div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Phone Number</label>
                <input
                  type="text"
                  name="phone"
                  value={form.phone}
                  onChange={handleChange}
                  className={`form-control ${error.phone ? "is-invalid" : ""}`}
                />
                {error.phone && (
                  <div className="invalid-feedback">{error.phone}</div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Date of Birth</label>
                <input
                  type="date"
                  name="dob"
                  value={form.dob}
                  onChange={handleChange}
                  className={`form-control ${error.dob ? "is-invalid" : ""}`}
                />
                {error.dob && (
                  <div className="invalid-feedback">{error.dob}</div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Gender</label>
                <select
                  name="gender"
                  value={form.gender}
                  onChange={handleChange}
                  className={`form-control ${error.gender ? "is-invalid" : ""}`}
                >
                  <option value="">Select</option>
                  <option>Male</option>
                  <option>Female</option>
                  <option>Other</option>
                </select>
                {error.gender && (
                  <div className="invalid-feedback">{error.gender}</div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Location / Time Zone</label>
                <input
                  type="text"
                  name="location"
                  value={form.location}
                  onChange={handleChange}
                  className={`form-control ${error.location ? "is-invalid" : ""}`}
                />
                {error.location && (
                  <div className="invalid-feedback">{error.location}</div>
                )}
              </div>

              <button
                type="button"
                className="btn btn-primary"
                onClick={nextStep}
              >
                Next
              </button>
            </>
          )}

          {/* Step 2: Health & Lifestyle */}
          {step === 2 && (
            <>
              <h5>🩺 Health & Lifestyle Information</h5>

              <div className="mb-3">
                <label className="form-label">Height (cm)</label>
                <input
                  type="number"
                  name="height"
                  value={form.height}
                  onChange={handleChange}
                  className={`form-control ${error.height ? "is-invalid" : ""}`}
                />
                {error.height && (
                  <div className="invalid-feedback">{error.height}</div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Weight (kg)</label>
                <input
                  type="number"
                  name="weight"
                  value={form.weight}
                  onChange={handleChange}
                  className={`form-control ${error.weight ? "is-invalid" : ""}`}
                />
                {error.weight && (
                  <div className="invalid-feedback">{error.weight}</div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Current Fitness Level</label>
                <input
                  type="text"
                  name="fitnessLevel"
                  value={form.fitnessLevel}
                  onChange={handleChange}
                  className={`form-control ${
                    error.fitnessLevel ? "is-invalid" : ""
                  }`}
                />
                {error.fitnessLevel && (
                  <div className="invalid-feedback">
                    {error.fitnessLevel}
                  </div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Medical Conditions</label>
                <input
                  type="text"
                  name="medicalConditions"
                  value={form.medicalConditions}
                  onChange={handleChange}
                  className={`form-control ${
                    error.medicalConditions ? "is-invalid" : ""
                  }`}
                />
                {error.medicalConditions && (
                  <div className="invalid-feedback">
                    {error.medicalConditions}
                  </div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Allergies / Dietary Restrictions</label>
                <input
                  type="text"
                  name="allergies"
                  value={form.allergies}
                  onChange={handleChange}
                  className="form-control"
                />
              </div>

              <div className="mb-3">
                <label className="form-label">Sleep Patterns</label>
                <input
                  type="text"
                  name="sleep"
                  value={form.sleep}
                  onChange={handleChange}
                  className={`form-control ${error.sleep ? "is-invalid" : ""}`}
                />
                {error.sleep && (
                  <div className="invalid-feedback">{error.sleep}</div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Smoking / Alcohol Habits</label>
                <input
                  type="text"
                  name="habits"
                  value={form.habits}
                  onChange={handleChange}
                  className="form-control"
                />
              </div>

              <div className="d-flex justify-content-between">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={prevStep}
                >
                  Back
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={nextStep}
                >
                  Next
                </button>
              </div>
            </>
          )}

          {/* Step 3: Goals & Preferences */}
          {step === 3 && (
            <>
              <h5>🎯 Goals & Preferences</h5>

              <div className="mb-3">
                <label className="form-label">Health Goals</label>
                <input
                  type="text"
                  name="goals"
                  value={form.goals}
                  onChange={handleChange}
                  className={`form-control ${error.goals ? "is-invalid" : ""}`}
                />
                {error.goals && (
                  <div className="invalid-feedback">{error.goals}</div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Preferred Coaching Style</label>
                <input
                  type="text"
                  name="coachingStyle"
                  value={form.coachingStyle}
                  onChange={handleChange}
                  className={`form-control ${
                    error.coachingStyle ? "is-invalid" : ""
                  }`}
                />
                {error.coachingStyle && (
                  <div className="invalid-feedback">{error.coachingStyle}</div>
                )}
              </div>

              <div className="mb-3">
                <label className="form-label">Workout Preferences</label>
                <input
                  type="text"
                  name="workoutPreferences"
                  value={form.workoutPreferences}
                  onChange={handleChange}
                  className="form-control"
                />
              </div>

              <div className="mb-3">
                <label className="form-label">Dietary Preferences</label>
                <input
                  type="text"
                  name="dietaryPreferences"
                  value={form.dietaryPreferences}
                  onChange={handleChange}
                  className="form-control"
                />
              </div>

              <div className="mb-3">
                <label className="form-label">Time Availability</label>
                <input
                  type="text"
                  name="timeAvailability"
                  value={form.timeAvailability}
                  onChange={handleChange}
                  className={`form-control ${
                    error.timeAvailability ? "is-invalid" : ""
                  }`}
                />
                {error.timeAvailability && (
                  <div className="invalid-feedback">
                    {error.timeAvailability}
                  </div>
                )}
              </div>

              <div className="d-flex justify-content-between">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={prevStep}
                >
                  Back
                </button>
                <button
                  type="submit"
                  className="btn btn-success"
                  disabled={submitting}
                >
                  {submitting ? "Submitting..." : "Submit"}
                </button>
              </div>
            </>
          )}
        </form>
      </div>
    </div>
  );
}
